/**
 * The `Event` enum of this pallet
 **/
export type PalletXcmEvent =
  /**
   * Execution of an XCM message was attempted.
   **/
  | { name: "Attempted"; data: { outcome: StagingXcmV5TraitsOutcome } }
  /**
   * An XCM message was sent.
   **/
  | {
      name: "Sent";
      data: {
        origin: StagingXcmV5Location;
        destination: StagingXcmV5Location;
        message: StagingXcmV5Xcm;
        messageId: FixedBytes<32>;
      };
    }
  /**
   * An XCM message failed to send.
   **/
  | {
      name: "SendFailed";
      data: {
        origin: StagingXcmV5Location;
        destination: StagingXcmV5Location;
        error: XcmV3TraitsSendError;
        messageId: FixedBytes<32>;
      };
    }
  /**
   * An XCM message failed to process.
   **/
  | {
      name: "ProcessXcmError";
      data: {
        origin: StagingXcmV5Location;
        error: XcmV5TraitsError;
        messageId: FixedBytes<32>;
      };
    }
  /**
   * Query response received which does not match a registered query. This may be because a
   * matching query was never registered, it may be because it is a duplicate response, or
   * because the query timed out.
   **/
  | {
      name: "UnexpectedResponse";
      data: { origin: StagingXcmV5Location; queryId: bigint };
    }
  /**
   * Query response has been received and is ready for taking with `take_response`. There is
   * no registered notification call.
   **/
  | {
      name: "ResponseReady";
      data: { queryId: bigint; response: StagingXcmV5Response };
    }
  /**
   * Query response has been received and query is removed. The registered notification has
   * been dispatched and executed successfully.
   **/
  | {
      name: "Notified";
      data: { queryId: bigint; palletIndex: number; callIndex: number };
    }
  /**
   * Query response has been received and query is removed. The registered notification
   * could not be dispatched because the dispatch weight is greater than the maximum weight
   * originally budgeted by this runtime for the query result.
   **/
  | {
      name: "NotifyOverweight";
      data: {
        queryId: bigint;
        palletIndex: number;
        callIndex: number;
        actualWeight: SpWeightsWeightV2Weight;
        maxBudgetedWeight: SpWeightsWeightV2Weight;
      };
    }
  /**
   * Query response has been received and query is removed. There was a general error with
   * dispatching the notification call.
   **/
  | {
      name: "NotifyDispatchError";
      data: { queryId: bigint; palletIndex: number; callIndex: number };
    }
  /**
   * Query response has been received and query is removed. The dispatch was unable to be
   * decoded into a `Call`; this might be due to dispatch function having a signature which
   * is not `(origin, QueryId, Response)`.
   **/
  | {
      name: "NotifyDecodeFailed";
      data: { queryId: bigint; palletIndex: number; callIndex: number };
    }
  /**
   * Expected query response has been received but the origin location of the response does
   * not match that expected. The query remains registered for a later, valid, response to
   * be received and acted upon.
   **/
  | {
      name: "InvalidResponder";
      data: {
        origin: StagingXcmV5Location;
        queryId: bigint;
        expectedLocation?: StagingXcmV5Location | undefined;
      };
    }
  /**
   * Expected query response has been received but the expected origin location placed in
   * storage by this runtime previously cannot be decoded. The query remains registered.
   *
   * This is unexpected (since a location placed in storage in a previously executing
   * runtime should be readable prior to query timeout) and dangerous since the possibly
   * valid response will be dropped. Manual governance intervention is probably going to be
   * needed.
   **/
  | {
      name: "InvalidResponderVersion";
      data: { origin: StagingXcmV5Location; queryId: bigint };
    }
  /**
   * Received query response has been read and removed.
   **/
  | { name: "ResponseTaken"; data: { queryId: bigint } }
  /**
   * Some assets have been placed in an asset trap.
   **/
  | {
      name: "AssetsTrapped";
      data: {
        hash: H256;
        origin: StagingXcmV5Location;
        assets: XcmVersionedAssets;
      };
    }
  /**
   * An XCM version change notification message has been attempted to be sent.
   *
   * The cost of sending it (borne by the chain) is included.
   **/
  | {
      name: "VersionChangeNotified";
      data: {
        destination: StagingXcmV5Location;
        result: number;
        cost: StagingXcmV5AssetAssets;
        messageId: FixedBytes<32>;
      };
    }
  /**
   * The supported version of a location has been changed. This might be through an
   * automatic notification or a manual intervention.
   **/
  | {
      name: "SupportedVersionChanged";
      data: { location: StagingXcmV5Location; version: number };
    }
  /**
   * A given location which had a version change subscription was dropped owing to an error
   * sending the notification to it.
   **/
  | {
      name: "NotifyTargetSendFail";
      data: {
        location: StagingXcmV5Location;
        queryId: bigint;
        error: XcmV5TraitsError;
      };
    }
  /**
   * A given location which had a version change subscription was dropped owing to an error
   * migrating the location to our new XCM format.
   **/
  | {
      name: "NotifyTargetMigrationFail";
      data: { location: XcmVersionedLocation; queryId: bigint };
    }
  /**
   * Expected query response has been received but the expected querier location placed in
   * storage by this runtime previously cannot be decoded. The query remains registered.
   *
   * This is unexpected (since a location placed in storage in a previously executing
   * runtime should be readable prior to query timeout) and dangerous since the possibly
   * valid response will be dropped. Manual governance intervention is probably going to be
   * needed.
   **/
  | {
      name: "InvalidQuerierVersion";
      data: { origin: StagingXcmV5Location; queryId: bigint };
    }
  /**
   * Expected query response has been received but the querier location of the response does
   * not match the expected. The query remains registered for a later, valid, response to
   * be received and acted upon.
   **/
  | {
      name: "InvalidQuerier";
      data: {
        origin: StagingXcmV5Location;
        queryId: bigint;
        expectedQuerier: StagingXcmV5Location;
        maybeActualQuerier?: StagingXcmV5Location | undefined;
      };
    }
  /**
   * A remote has requested XCM version change notification from us and we have honored it.
   * A version information message is sent to them and its cost is included.
   **/
  | {
      name: "VersionNotifyStarted";
      data: {
        destination: StagingXcmV5Location;
        cost: StagingXcmV5AssetAssets;
        messageId: FixedBytes<32>;
      };
    }
  /**
   * We have requested that a remote chain send us XCM version change notifications.
   **/
  | {
      name: "VersionNotifyRequested";
      data: {
        destination: StagingXcmV5Location;
        cost: StagingXcmV5AssetAssets;
        messageId: FixedBytes<32>;
      };
    }
  /**
   * We have requested that a remote chain stops sending us XCM version change
   * notifications.
   **/
  | {
      name: "VersionNotifyUnrequested";
      data: {
        destination: StagingXcmV5Location;
        cost: StagingXcmV5AssetAssets;
        messageId: FixedBytes<32>;
      };
    }
  /**
   * Fees were paid from a location for an operation (often for using `SendXcm`).
   **/
  | {
      name: "FeesPaid";
      data: { paying: StagingXcmV5Location; fees: StagingXcmV5AssetAssets };
    }
  /**
   * Some assets have been claimed from an asset trap
   **/
  | {
      name: "AssetsClaimed";
      data: {
        hash: H256;
        origin: StagingXcmV5Location;
        assets: XcmVersionedAssets;
      };
    }
  /**
   * A XCM version migration finished.
   **/
  | { name: "VersionMigrationFinished"; data: { version: number } }
  /**
   * An `aliaser` location was authorized by `target` to alias it, authorization valid until
   * `expiry` block number.
   **/
  | {
      name: "AliasAuthorized";
      data: {
        aliaser: StagingXcmV5Location;
        target: StagingXcmV5Location;
        expiry?: bigint | undefined;
      };
    }
  /**
   * `target` removed alias authorization for `aliaser`.
   **/
  | {
      name: "AliasAuthorizationRemoved";
      data: { aliaser: StagingXcmV5Location; target: StagingXcmV5Location };
    }
  /**
   * `target` removed all alias authorizations.
   **/
  | {
      name: "AliasesAuthorizationsRemoved";
      data: { target: StagingXcmV5Location };
    };

export type StagingXcmV5TraitsOutcome =
  | { type: "Complete"; value: { used: SpWeightsWeightV2Weight } }
  | {
      type: "Incomplete";
      value: {
        used: SpWeightsWeightV2Weight;
        error: StagingXcmV5TraitsInstructionError;
      };
    }
  | { type: "Error"; value: StagingXcmV5TraitsInstructionError };

export type StagingXcmV5TraitsInstructionError = {
  index: number;
  error: XcmV5TraitsError;
};

export type XcmV3TraitsSendError =
  | "NotApplicable"
  | "Transport"
  | "Unroutable"
  | "DestinationUnsupported"
  | "ExceedsMaxMessageSize"
  | "MissingArgument"
  | "Fees";

/**
 * The `Event` enum of this pallet
 **/
export type CumulusPalletXcmEvent =
  /**
   * Downward message is invalid XCM.
   * \[ id \]
   **/
  | { name: "InvalidFormat"; data: FixedBytes<32> }
  /**
   * Downward message is unsupported version of XCM.
   * \[ id \]
   **/
  | { name: "UnsupportedVersion"; data: FixedBytes<32> }
  /**
   * Downward message executed with the given outcome.
   * \[ id, outcome \]
   **/
  | {
      name: "ExecutedDownward";
      data: [FixedBytes<32>, StagingXcmV5TraitsOutcome];
    };

/**
 * The `Event` enum of this pallet
 **/
export type PalletMessageQueueEvent =
  /**
   * Message discarded due to an error in the `MessageProcessor` (usually a format error).
   **/
  | {
      name: "ProcessingFailed";
      data: {
        /**
         * The `blake2_256` hash of the message.
         **/
        id: H256;

        /**
         * The queue of the message.
         **/
        origin: CumulusPrimitivesCoreAggregateMessageOrigin;

        /**
         * The error that occurred.
         *
         * This error is pretty opaque. More fine-grained errors need to be emitted as events
         * by the `MessageProcessor`.
         **/
        error: FrameSupportMessagesProcessMessageError;
      };
    }
  /**
   * Message is processed.
   **/
  | {
      name: "Processed";
      data: {
        /**
         * The `blake2_256` hash of the message.
         **/
        id: H256;

        /**
         * The queue of the message.
         **/
        origin: CumulusPrimitivesCoreAggregateMessageOrigin;

        /**
         * How much weight was used to process the message.
         **/
        weightUsed: SpWeightsWeightV2Weight;

        /**
         * Whether the message was processed.
         *
         * Note that this does not mean that the underlying `MessageProcessor` was internally
         * successful. It *solely* means that the MQ pallet will treat this as a success
         * condition and discard the message. Any internal error needs to be emitted as events
         * by the `MessageProcessor`.
         **/
        success: boolean;
      };
    }
  /**
   * Message placed in overweight queue.
   **/
  | {
      name: "OverweightEnqueued";
      data: {
        /**
         * The `blake2_256` hash of the message.
         **/
        id: FixedBytes<32>;

        /**
         * The queue of the message.
         **/
        origin: CumulusPrimitivesCoreAggregateMessageOrigin;

        /**
         * The page of the message.
         **/
        pageIndex: number;

        /**
         * The index of the message within the page.
         **/
        messageIndex: number;
      };
    }
  /**
   * This page was reaped.
   **/
  | {
      name: "PageReaped";
      data: {
        /**
         * The queue of the page.
         **/
        origin: CumulusPrimitivesCoreAggregateMessageOrigin;

        /**
         * The index of the page.
         **/
        index: number;
      };
    };

export type FrameSupportMessagesProcessMessageError =
  | { type: "BadFormat" }
  | { type: "Corrupt" }
  | { type: "Unsupported" }
  | { type: "Overweight"; value: SpWeightsWeightV2Weight }
  | { type: "Yield" }
  | { type: "StackLimitReached" };

